import React, { Component } from 'react'
import {
  View,
  Text,
  StyleSheet,
  SectionList,
  FlatList,
  Animated,
  ScrollView,
  Platform,
  Image, 
  TouchableOpacity,
  Button
} from 'react-native'
import {Icon} from 'react-native-elements';
import firebase from 'react-native-firebase';
import axios from "axios";
import Modal from 'react-native-modal';
import {NavigationActions} from 'react-navigation';


const Header_Maximum_Height = 25 * vh;
 
const Header_Minimum_Height = 0 * vh;

const db = firebase.firestore();

class ClassUpdates extends Component {
  constructor() {
    super();
    this.AnimatedHeaderValue = new Animated.Value(0);
    this.timeSince = this.timeSince.bind(this);
    this.state = {
      updates: [],
      n_updates: 0,
      selectedUpdate: [],
      updatesModal: false
    }
  }

async componentDidMount() {
  axios.get('https://classcast-198812.appspot.com/users/announcements_updated')
      .then(function (response){
        this.setState({n_updates: response.data.length});
        this.setState({updates: response.data.sort(function(a,b){ return new Date(b.time) - new Date(a.time) }) });
      }.bind(this))
      .catch(function(error){
        console.log('naldndskajdewnkesakerror1: '+error);
      });
  }

  timeSince(date) {

    //ToastArndroid.show(date, ToastAndroid.SHORT);
    var dif =  new Date() - date;
    var seconds = Math.floor(parseFloat(dif / 1000));


    var interval = Math.floor(parseFloat(seconds / 31536000));

    if (interval > 1) {
        return interval + " years";
    }
    interval = Math.floor(parseFloat(seconds / 2592000));
    if (interval > 1) {
        return interval + " months";
    }
    interval = Math.floor(parseFloat(seconds / 86400));
    if (interval > 1) {
        return interval + " days";
    }
    interval = Math.floor(parseFloat(seconds / 3600));
    if (interval > 1) {
        return interval + " hours";
    }
    interval = Math.floor(parseFloat(seconds / 60));
    if (interval > 1) {
        return interval + " minutes";
    }
    //ToastAndroid.show("auaaaa" + Math.floor(parseFloat(seconds))+ new Date() + typeof(Math.floor(parseFloat(seconds))) + typeof(seconds) + typeof(interval), ToastAndroid.SHORT);
  
    return Math.floor(parseFloat(seconds)) + " seconds";
  }

  _renderItem ({item, index}) {
    console.log("date1: "+item.time);
    console.log("data1: "+this.timeSince(new Date(item.time)));
    return (
        <TouchableOpacity style={{flex: 1, flexDirection: 'row', marginTop: 0.8 * vh, marginBottom: 0.8 * vh, width: '98%', alignSelf: 'center', elevation: 2, borderRadius: 2 * vw}} 
          onPress={() => {
            this.setState({selectedUpdate: item});
            this.setState({updatesModal: true}) 
          }}>
            <View style ={{flexDirection:'row', borderRadius:5, width: '100%', marginTop: 1 * vh, marginBottom: 1 * vh, alignSelf: 'flex-start', padding: 2 * vw}}>
              <Icon     name='message'
                        color='grey'
                        type='material'
                        size= {35} />
              <View style={{marginLeft: 2 * vw, width: '100%'}}>
                <View style={{flexDirection: 'row', justifyContent: 'space-between', width: '80%'}}>
                  <Text style={{fontFamily: 'Montserrat-SemiBold', fontSize: 15, color:'grey', fontWeight: 'bold', textTransform: 'capitalize'}}> {item.type} </Text>
                  <Text style={{color: '#4286f4', fontSize: 15, fontStyle: 'italic', textAlign: 'center'}}>{this.timeSince(new Date(item.time)) + ' ago'}</Text>
                </View>
                <Text style={{ fontSize: 16, color:'black', width: '80%'}}> {item.message} </Text>
              </View>
            </View>
        </TouchableOpacity>
         );
    }
  

  render () {
    const AnimateHeaderBackgroundColor = this.AnimatedHeaderValue.interpolate(
      {
          inputRange: [ 0, ( Header_Maximum_Height - Header_Minimum_Height )  ],

          outputRange: [ '#009688', '#00BCD4' ],

          extrapolate: 'clamp'
      });

      const AnimateHeaderHeight = this.AnimatedHeaderValue.interpolate(
          {
              inputRange: [ 0, ( Header_Maximum_Height - Header_Minimum_Height ) ],
  
              outputRange: [ Header_Maximum_Height, Header_Minimum_Height ],
  
              extrapolate: 'clamp'
          });

    return (
      <View style={styles.container}>

        <Modal
            backdropOpacity={0.6}
            backdropColor="black"
            transparent={true}
            isVisible={this.state.updatesModal}
            onRequestClose={() => {
              this.setState({updatesModal: false})
            }}>
            <View style={[styles.tncModal, {height: 'auto'}]}>
              <Text style={styles.tncHeadingBig}>Announcement</Text>
              <ScrollView>
                <View style={{flexDirection: 'column', alignItems: 'flex-start'}}>

                  <View style={{flexDirection: 'row', alignItems: 'center'}}>
                    <Text style={{fontFamily: 'Montserrat-Regular', fontSize: 4 * vw, textDecorationLine: 'none', color: 'black'}}>{this.state.selectedUpdate.message}</Text>
                  </View>
                  { this.state.selectedUpdate.action != 'null' && this.state.selectedUpdate.action != 'expired' &&
                  <View style={{alignSelf: 'center', marginTop: 2 * vh}}>
                    <Button
                        onPress={()=> {
                          this.setState({updatesModal: false});
                          if(this.state.selectedUpdate.action == 'pdf')
                          {
                            const navigateAction = NavigationActions.navigate({
                              routeName: 'pdfViewer',
                              params: {
                                url: this.state.selectedUpdate.payload
                              },
                            });
                            this.props.navigation.dispatch(navigateAction);
                          } 
                          else if(this.state.selectedUpdate.action == 'weburl')
                          {
                            const navigateAction = NavigationActions.navigate({
                              routeName: 'webViewer',
                              params: {
                                url: this.state.selectedUpdate.payload
                              },
                            });
                            this.props.navigation.dispatch(navigateAction);
                          } 

                          else if(this.state.selectedUpdate.action == 'start')
                          {
                            const navigateAction = NavigationActions.navigate({
                              routeName: 'loading',
                              params: {
                                duration: 15,
                                goal: 'Practice Test',
                                test_id: this.state.selectedUpdate.payload,
                                chapterAvailable: false,
                                path: 'TabB_test',
                                chapter_name: '',
                                subject: '',
                              }
                            });
                            this.props.navigation.dispatch(navigateAction);
                          }

                        }}
                        title="Open"
                        color="#841584"
                        accessibilityLabel="Learn more about this purple button"
                      />
                    </View>
                  }
                </View>
                </ScrollView>
            </View>

        </Modal>

        <ScrollView 
        keyboardShouldPersistTaps='handled'
        scrollEventThrottle = { 16 }

        style ={{zIndex: 1, width: '100%'}}
        showsVerticalScrollIndicator={false}
        contentContainerStyle = {{ paddingTop: Header_Maximum_Height }}
        onScroll = { 
          Animated.event(
          [{ nativeEvent: { contentOffset: { y: this.AnimatedHeaderValue }}}]
        )}>
              <View style = {{height: 30 * vh, width: '98%', marginTop: -15 * vh, alignSelf:'center', elevation: 9, zIndex: 1, borderRadius: 1 * vw, marginBottom: 3 * vh, backgroundColor: 'rgba(365,365,365,0.9)'}}>
              <View style={{ justifyContent: 'center', alignItems: 'center', height: 16 * vh, width: 16 * vh, alignSelf: 'center', backgroundColor: '#6044f0', borderRadius: 10 * vh, zIndex: 2, elevation: 10, marginTop: -8 * vh}}>
                <Image
                  source= {{uri: this.props.navigation.state.params.data.photo}}
                  style={{
                    width: '100%',
                    height: '100%',
                    borderRadius: 10,
                  }}
                />
              </View>
              <View
                style={{
                  height: 3 * vh,
                  marginTop: 1 * vh,
                  alignSelf:'center',
                  justifyContent: 'center',
                  alignItems: 'center'
                }}
              >
              <Text
                  style={{
                    fontFamily: 'ProximaNova-regular',
                    fontSize: 6 * vw,
                    color: 'black',
                    alignSelf: 'center'
                  }}
                >
                  {this.props.navigation.state.params.data.firstname+ ' '+this.props.navigation.state.params.data.lastname+ ' Sir'}
                </Text>
              </View>
                <View
                style={{
                  width: '98%',
                  marginTop: 0.5 * vh,
                  flexDirection: 'row',
                  justifyContent: 'center',
                  alignItems: 'center',
                  alignSelf:'center', 
                  paddingLeft: 4 * vw,
                  paddingRight: 4 * vw,
                }}
              >
              <Image
                  source= {{uri: 'data:image/png;base64,'}}
                  style={{
                    width: 3 * vh,
                    height: 3 * vh,
                    marginRight: 2 * vw,
                  }}
                />
                <Text
                  style={{
                    fontFamily: 'ProximaNova-regular',
                    fontSize: 4 * vw,
                    color: 'gray',
                    textAlign: 'left',
                  }}
                >
                  {this.props.navigation.state.params.data.coaching_name+', '+this.props.navigation.state.params.data.area}
                </Text>
              </View>
              <View
                style={{
                  flex: 9,
                  height: 8 * vh,
                  flexDirection: 'row',
                  justifyContent: 'center',
                  alignItems: 'center',
                }}
              >
                <View style={{flexDirection: 'column', flex: 3, justifyContent: 'space-between', alignItems: 'center',}}>
                  <Text style ={{fontFamily: 'ProximaNova-regular',fontSize: 4 * vw,color: 'black',alignSelf: 'center'}}>{this.props.navigation.state.params.data.courses.split(",").length+ ' courses'}</Text>
                  <Image
                  source= {{uri: 'data:image/png;base64,'}}
                  style={{
                    width: 12 * vw,
                    height: 12 * vw,
                    marginTop: 0 * vh
                  }}
                />
                </View>
                <View style={{flexDirection: 'column', flex: 3, justifyContent: 'space-between', alignItems: 'center',}}>
                <Text style ={{fontFamily: 'ProximaNova-regular',fontSize: 4 * vw,color: 'black',alignSelf: 'center'}}>{this.props.navigation.state.params.data.subject}</Text>
                  <Image
                  source= {{uri: this.props.navigation.state.params.data.subject == 'Chemistry' ? 'data:image/png;base64,'
                            : this.props.navigation.state.params.data.subject == 'Physics' ? 'data:image/png;base64,'
                            : 'data:image/png;base64,'
                }}
                  style={{
                    width: 12 * vw,
                    height: 12 * vw,
                  }}
                />
                </View>
                <View style={{flexDirection: 'column', flex: 3, justifyContent: 'space-between',alignItems: 'center',}}>
                  <Text style ={{fontFamily: 'ProximaNova-regular',fontSize: 4 * vw,color: 'black',alignSelf: 'center'}}>{this.props.navigation.state.params.data.goal}</Text>
                  <Image
                  source= {{uri: 'data:image/png;base64,'}}
                  style={{
                    width: 12 * vw,
                    height: 12 * vw,
                  }}
                />
                </View>
              </View>
              </View>
              <Text style ={{fontFamily: 'ProximaNova-Bold',fontSize: 5 * vw,color: 'black', textAlign: 'left', marginLeft: 2 * vw, marginBottom: 1 * vh}}>Updates</Text>
        <FlatList
          data={this.state.updates}
          showsVerticalScrollIndicator={false}
          renderItem={this._renderItem.bind(this) }
          keyExtractor={(item, index) => index.toString()}
        />
        </ScrollView>
        <Animated.View style = {[ styles.HeaderStyle, { height: AnimateHeaderHeight  } ]}>
      <View style={{ width: '100%', alignItems:'center', justifyContent: 'center'}}>
                <Image
                  source= {{uri: 'data:image/png;base64,'}}
                  style={{
                    width: '100%',
                    height: '100%',
                  }}
                />
                
              </View>
    </Animated.View>
      </View>
      )
  }
}

export default ClassUpdates

